namespace Acme\Component\Kitdemo\Administrator\Controller;

defined('_JEXEC') or die;

use Acme\Component\Kitdemo\Administrator\Helper\AccountLinkHelper;
use Joomla\CMS\Factory;
use Joomla\CMS\MVC\Controller\BaseController;

/**
 * What the "Link your account" panel posts to. The token and permission checks
 * are in AccountLinkHelper::handleRequest().
 */
class AccountController extends BaseController
{
    public function run(): void
    {
        $app = Factory::getApplication();

        $app->setHeader('Content-Type', 'application/json; charset=utf-8', true);
        $app->sendHeaders();

        echo AccountLinkHelper::handleRequest();

        $app->close();
    }
}
